MQ['2-0']=[
 {t:'mc',g:A,q:'곡선 $y=x^2-2x$와 $x$축으로 둘러싸인 부분의 넓이는?',o:['$\\frac{4}{3}$','1','$\\frac{2}{3}$','2','$\\frac{8}{3}$'],a:0,e:'$0\\le x\\le2$에서 $y\\le0$이므로 $-\\int_0^2(x^2-2x)dx=\\frac{4}{3}$이에요.'},
 {t:'mc',g:A,q:'곡선 $y=x^3$과 $x$축 및 두 직선 $x=-1$, $x=1$로 둘러싸인 부분의 넓이는?',o:['$\\frac{1}{2}$','0','$\\frac{1}{4}$','1','2'],a:0,e:'원점 대칭이므로 $2\\int_0^1x^3dx=\\frac{1}{2}$이에요. 정적분 값 0과 구별해요.'},
 {t:'mc',g:B,q:'곡선 $y=x^2$과 직선 $y=x$로 둘러싸인 부분의 넓이는?',o:['$\\frac{1}{6}$','$\\frac{1}{3}$','$\\frac{1}{2}$','$\\frac{1}{12}$','$\\frac{2}{3}$'],a:0,e:'교점은 $x=0, 1$이고 $\\int_0^1(x-x^2)dx=\\frac{1}{6}$이에요.'},
 {t:'ox',g:A,q:'$\\int_a^b f(x)dx$의 값은 항상 곡선 $y=f(x)$와 $x$축 및 두 직선 $x=a$, $x=b$로 둘러싸인 부분의 넓이와 같다.',a:false,e:'$f(x)<0$인 부분이 있으면 정적분 값과 넓이가 달라요.'},
 {t:'sh',g:A,q:'곡선 $y=-x^2+4$와 $x$축으로 둘러싸인 부분의 넓이를 구하시오. (분수는 a/b 꼴로)',a:['32/3'],m:'32/3',e:'$\\int_{-2}^2(4-x^2)dx=2\\left(8-\\frac{8}{3}\\right)=\\frac{32}{3}$이에요.'},
 {t:'mc',g:B,q:'곡선 $y=x^2$과 직선 $y=x+2$로 둘러싸인 부분의 넓이는?',o:['$\\frac{9}{2}$','4','$\\frac{7}{2}$','5','$\\frac{11}{2}$'],a:0,e:'교점은 $x=-1, 2$이고 $\\int_{-1}^2(x+2-x^2)dx=\\frac{9}{2}$예요.'},
 {t:'sh',g:A,q:'곡선 $y=x^3-x$와 $x$축으로 둘러싸인 부분의 넓이를 구하시오. (분수는 a/b 꼴로)',a:['1/2'],m:'1/2',e:'$x$축과 $x=-1, 0, 1$에서 만나고 원점 대칭이므로 $2\\int_0^1(x-x^3)dx=\\frac{1}{2}$이에요.'},
 {t:'ox',g:B,q:'두 곡선 $y=f(x)$, $y=g(x)$와 두 직선 $x=a$, $x=b$로 둘러싸인 부분의 넓이는 $\\int_a^b|f(x)-g(x)|dx$이다.',a:true,e:'위 곡선에서 아래 곡선을 뺀 것을 적분하므로 절댓값으로 나타낼 수 있어요.'},
 {t:'mc',g:A,q:'곡선 $y=x^2-4$와 $x$축 및 두 직선 $x=0$, $x=3$으로 둘러싸인 부분의 넓이는?',o:['$\\frac{23}{3}$','$\\frac{16}{3}$','3','7','$\\frac{25}{3}$'],a:0,e:'$\\int_0^2(4-x^2)dx=\\frac{16}{3}$, $\\int_2^3(x^2-4)dx=\\frac{7}{3}$이므로 합은 $\\frac{23}{3}$이에요.'},
 {t:'mc',g:B,q:'두 곡선 $y=x^2$, $y=-x^2+2$로 둘러싸인 부분의 넓이는?',o:['$\\frac{8}{3}$','$\\frac{4}{3}$','2','$\\frac{10}{3}$','4'],a:0,e:'교점은 $x=\\pm1$이고 $\\int_{-1}^1(2-2x^2)dx=\\frac{8}{3}$이에요.'},
 {lv:'x',t:'sh',g:D,q:'곡선 $y=x^2-ax$와 $x$축으로 둘러싸인 부분의 넓이가 36일 때, 양수 $a$의 값을 구하시오.',a:['6'],m:'6',e:'$x$축과 $x=0, a$에서 만나므로 넓이는 $\\frac{a^3}{6}=36$, $a=6$이에요.'},
 {lv:'x',t:'mc',g:B,q:'곡선 $y=x^3$과 직선 $y=4x$로 둘러싸인 부분의 넓이는?',o:['8','4','6','10','16'],a:0,e:'교점은 $x=0, \\pm2$이고 원점 대칭이므로 $2\\int_0^2(4x-x^3)dx=2(8-4)=8$이에요.'},
 {lv:'x',t:'mc',g:B,q:'곡선 $y=x^2$ 위의 점 $(1, 1)$에서의 접선과 이 곡선 및 $y$축으로 둘러싸인 부분의 넓이는?',o:['$\\frac{1}{3}$','$\\frac{1}{6}$','$\\frac{1}{2}$','$\\frac{2}{3}$','1'],a:0,e:'접선은 $y=2x-1$이고 $\\int_0^1(x^2-2x+1)dx=\\frac{1}{3}$이에요.'},
 {lv:'x',t:'mc',g:B,q:'두 곡선 $y=x^2-2x$, $y=-x^2+2x$로 둘러싸인 부분의 넓이는?',o:['$\\frac{8}{3}$','$\\frac{4}{3}$','2','$\\frac{16}{3}$','4'],a:0,e:'교점은 $x=0, 2$이고 $\\int_0^2(4x-2x^2)dx=8-\\frac{16}{3}=\\frac{8}{3}$이에요.'},
 {lv:'x',t:'sh',g:D,q:'곡선 $y=x^2$과 직선 $y=k$로 둘러싸인 부분의 넓이가 $\\frac{32}{3}$일 때, 양수 $k$의 값을 구하시오.',a:['4'],m:'4',e:'교점은 $x=\\pm\\sqrt{k}$이고 넓이는 $\\int_{-\\sqrt{k}}^{\\sqrt{k}}(k-x^2)dx=\\frac{4}{3}k\\sqrt{k}=\\frac{32}{3}$이에요. $k\\sqrt{k}=8$이므로 $k=4$예요.'},
 {lv:'x',t:'mc',g:A,q:'옳은 것만을 <보기>에서 있는 대로 고른 것은?\n\n<보기>\nㄱ. $\\int_{-1}^2xdx=\\frac{3}{2}$\nㄴ. 직선 $y=x$와 $x$축 및 두 직선 $x=-1$, $x=2$로 둘러싸인 부분의 넓이는 $\\frac{5}{2}$이다.\nㄷ. ㄴ의 넓이는 $\\int_{-1}^2xdx$의 값과 같다.',o:['ㄱ, ㄴ','ㄱ','ㄴ','ㄷ','ㄱ, ㄴ, ㄷ'],a:0,e:'넓이는 $\\frac{1}{2}+2=\\frac{5}{2}$이고 정적분 값은 $2-\\frac{1}{2}=\\frac{3}{2}$이라 서로 달라요.'},
 {lv:'x',t:'mc',g:A,q:'곡선 $y=x^3-3x^2+2x$와 $x$축으로 둘러싸인 부분의 넓이는?',o:['$\\frac{1}{2}$','$\\frac{1}{4}$','0','1','$\\frac{3}{4}$'],a:0,e:'$x$축과 $x=0, 1, 2$에서 만나요. $\\int_0^1=\\frac{1}{4}$이고 $[1, 2]$에서도 넓이 $\\frac{1}{4}$이므로 합은 $\\frac{1}{2}$이에요.'},
 {lv:'x',t:'sh',g:D,q:'곡선 $y=x^2$과 직선 $y=mx$로 둘러싸인 부분의 넓이가 $\\frac{9}{2}$일 때, 양수 $m$의 값을 구하시오.',a:['3'],m:'3',e:'교점은 $x=0, m$이고 넓이는 $\\frac{m^3}{6}=\\frac{9}{2}$, $m=3$이에요.'},
 {lv:'x',t:'mc',g:B,q:'두 곡선 $y=x^3-x$, $y=x^2-1$로 둘러싸인 부분의 넓이는?',o:['$\\frac{4}{3}$','1','$\\frac{2}{3}$','$\\frac{5}{3}$','2'],a:0,e:'$x^3-x-(x^2-1)=(x-1)^2(x+1)$이므로 교점은 $x=-1, 1$이고 이 구간에서 $y=x^3-x$가 위에 있어요. $\\int_{-1}^1(x^3-x^2-x+1)dx=\\frac{4}{3}$이에요.'},
 {lv:'x',t:'mc',g:A,q:'곡선 $y=x^2-4x+3$과 $x$축으로 둘러싸인 부분의 넓이를 $S_1$, 이 곡선과 $x$축 및 $y$축으로 둘러싸인 부분의 넓이를 $S_2$라 할 때, $S_1+S_2$의 값은?',o:['$\\frac{8}{3}$','$\\frac{4}{3}$','2','$\\frac{10}{3}$','4'],a:0,e:'$S_1=\\int_1^3\\{-(x^2-4x+3)\\}dx=\\frac{4}{3}$, $S_2=\\int_0^1(x^2-4x+3)dx=\\frac{4}{3}$이에요.'}
];
MMK['2-0']=[
 {g:A,q:'곡선 $y=x^2-4x$와 $x$축으로 둘러싸인 부분의 넓이는?',o:['$\\frac{32}{3}$','8','$\\frac{16}{3}$','$\\frac{28}{3}$','12'],a:0,e:'$\\frac{1\\times4^3}{6}=\\frac{32}{3}$이에요.'},
 {g:B,q:'곡선 $y=x^2$과 직선 $y=-x+2$로 둘러싸인 부분의 넓이는?',o:['$\\frac{9}{2}$','4','$\\frac{7}{2}$','$\\frac{11}{2}$','6'],a:0,e:'교점은 $x=-2, 1$이고 넓이는 $\\frac{3^3}{6}=\\frac{9}{2}$예요.'},
 {g:A,q:'곡선 $y=x^3-4x$와 $x$축으로 둘러싸인 부분의 넓이는?',o:['8','4','6','10','16'],a:0,e:'$x=0, \\pm2$에서 만나고 원점 대칭이므로 $2\\int_0^2(4x-x^3)dx=8$이에요.'},
 {g:A,q:'곡선 $y=x^2+1$과 $x$축 및 두 직선 $x=0$, $x=3$으로 둘러싸인 부분의 넓이는?',o:['12','9','10','13','15'],a:0,e:'$\\int_0^3(x^2+1)dx=9+3=12$예요.'},
 {g:D,q:'곡선 $y=x^2-ax$와 $x$축으로 둘러싸인 부분의 넓이가 $\\frac{4}{3}$일 때, 양수 $a$의 값은?',o:['2','1','$\\frac{3}{2}$','3','4'],a:0,e:'넓이는 $\\frac{a^3}{6}=\\frac{4}{3}$이므로 $a^3=8$, $a=2$예요.'},
 {g:B,hd:1,q:'곡선 $y=x^3$ 위의 점 $(1, 1)$에서의 접선과 이 곡선으로 둘러싸인 부분의 넓이는?',o:['$\\frac{27}{4}$','$\\frac{9}{4}$','$\\frac{27}{8}$','6','$\\frac{15}{2}$'],a:0,e:'접선은 $y=3x-2$이고 $x^3-3x+2=(x-1)^2(x+2)$이므로 다시 만나는 점은 $x=-2$예요. $\\int_{-2}^1(x^3-3x+2)dx=\\frac{27}{4}$이에요.'},
 {g:B,q:'두 곡선 $y=x^2$, $y=x^3$으로 둘러싸인 부분의 넓이는?',o:['$\\frac{1}{12}$','$\\frac{1}{6}$','$\\frac{1}{4}$','$\\frac{1}{3}$','$\\frac{7}{12}$'],a:0,e:'교점은 $x=0, 1$이고 $0\\le x\\le1$에서 $x^2\\ge x^3$이므로 $\\int_0^1(x^2-x^3)dx=\\frac{1}{12}$이에요.'},
 {g:A,q:'곡선 $y=2x^2-8$과 $x$축으로 둘러싸인 부분의 넓이는?',o:['$\\frac{64}{3}$','$\\frac{32}{3}$','16','24','$\\frac{80}{3}$'],a:0,e:'교점은 $x=\\pm2$이고 넓이는 $\\frac{2\\times4^3}{6}=\\frac{64}{3}$이에요.'},
 {g:B,q:'곡선 $y=x^2$과 직선 $y=4$로 둘러싸인 부분의 넓이는?',o:['$\\frac{32}{3}$','8','$\\frac{16}{3}$','12','16'],a:0,e:'$\\int_{-2}^2(4-x^2)dx=\\frac{32}{3}$이에요.'},
 {g:D,hd:1,t:'sh',q:'곡선 $y=x^2-2x$와 직선 $y=kx$로 둘러싸인 부분의 넓이가 36일 때, 양수 $k$의 값을 구하시오.',a:['4'],m:'4',e:'$x^2-2x=kx$에서 교점은 $x=0, k+2$예요. 넓이는 $\\frac{(k+2)^3}{6}=36$이므로 $k+2=6$, $k=4$예요.'},
 {g:A,q:'곡선 $y=x^3-x^2-2x$와 $x$축으로 둘러싸인 부분의 넓이는?',o:['$\\frac{37}{12}$','$\\frac{8}{3}$','$\\frac{5}{12}$','3','$\\frac{9}{4}$'],a:0,e:'$x$축과 $x=-1, 0, 2$에서 만나요. $\\int_{-1}^0=\\frac{5}{12}$, $\\int_0^2=-\\frac{8}{3}$이므로 넓이는 $\\frac{5}{12}+\\frac{8}{3}=\\frac{37}{12}$이에요.'},
 {g:B,t:'sh',q:'곡선 $y=x^2$과 직선 $y=2x$로 둘러싸인 부분의 넓이를 구하시오. (분수는 a/b 꼴로)',a:['4/3'],m:'4/3',e:'교점은 $x=0, 2$이고 $\\int_0^2(2x-x^2)dx=\\frac{4}{3}$이에요.'},
 {g:A,t:'sh',q:'곡선 $y=x^2-6x+5$와 $x$축으로 둘러싸인 부분의 넓이를 구하시오. (분수는 a/b 꼴로)',a:['32/3'],m:'32/3',e:'교점은 $x=1, 5$이고 넓이는 $\\frac{4^3}{6}=\\frac{32}{3}$이에요.'}
];
Object.assign(TIPS,{[A]:'넓이 $=\\int_a^b|f(x)|dx$. $x$축 아래는 부호를 바꾸고, $x$축과 만나는 점에서 구간을 나눠요.',[B]:'두 곡선 사이 넓이: 교점을 구하고 (위 곡선) − (아래 곡선)을 적분해요. 이차함수는 $\\frac{|a|(\\beta-\\alpha)^3}{6}$.',[D]:'넓이가 주어지면 교점을 문자로 나타내 넓이 식을 세워 미지수를 구해요.'});
